script:
// Forgó fázor és a szinuszgörbe / A rotating phasor and its sine wave
//   u(t) = Û · sin(ωt + φ),   ω = 2πf,   U = Û / √2
// A fázor függőleges vetülete minden pillanatban a feszültség pillanatértéke.
// The phasor's vertical projection is the instantaneous voltage at every moment.
stage(1000, 600, "#fbfbf8");
title({hu: "Forgó fázor és szinuszgörbe", en: "Rotating phasor and sine wave"});
timeScale(0.004);                              // 50 Hz: egy 20 ms-os periódus 5 s alatt fut le / one 20 ms period lasts 5 s
param("Um", {hu: "Csúcsérték Û", en: "Peak value Û"}, 50, 400, 325, 5, "V");
param("f", {hu: "Frekvencia f", en: "Frequency f"}, 10, 100, 50, 1, "Hz");
param("phi", {hu: "Kezdőfázis φ", en: "Initial phase φ"}, -180, 180, 0, 5, "°");
plotWindow(0.04);                              // két periódus 50 Hz-en: 2 / 50 s / two periods at 50 Hz

let wt = 0;                                    // ωt, a fázisszög (rad), integrálva, így f változtatásakor sem ugrik / integrated, so it never jumps
update(dt => { wt += 2 * PI * P.f * dt; });

draw(t => {
  const cx0 = 220, cy0 = 300, kU = 150 / 400;  // a fázor középpontja; 1 V = 0,375 px / phasor centre; 1 V = 0.375 px
  const a = wt + deg(P.phi), L = P.Um * kU;
  const u = P.Um * sin(a);                     // pillanatérték / instantaneous value u = Û·sin(ωt + φ)
  circle(cx0, cy0, L, {stroke: C.light, lw: 1});
  phasor(cx0, cy0, L, a, {stroke: C.blue, lw: 4}, "Û");
  // A görbe: az utolsó teljes periódus a kör jobb oldalán / the wave: the last full period right of the circle
  const x0 = 420, w = 520, pts = [];
  for (let k = 0; k <= 120; k++) {
    const back = k / 120 * 2 * PI;             // mennyivel korábbi fázis ez a pont / how far back in phase this point is
    pts.push([x0 + back / (2 * PI) * w, cy0 - P.Um * kU * sin(a - back)]);
  }
  line(x0, cy0, x0 + w, cy0, {stroke: C.gray, lw: 1});
  polyline(pts, {stroke: C.blue, lw: 2.5});
  // Vetítővonal a fázor hegyétől a görbe elejéig / projection line from the phasor tip to the start of the wave
  line(cx0 + L * cos(a), cy0 - L * sin(a), x0, cy0 - u * kU, {stroke: C.gray, dash: [4, 4], lw: 1});
  circle(x0, cy0 - u * kU, 6, {fill: C.red, stroke: null});
  text("u = " + fmt(u, 0) + " V", x0, 120, {size: 20, bold: true});
  text({hu: "korábban →", en: "earlier →"}, x0 + w, cy0 + 170, {size: 13, color: C.gray, align: "right"});
  show({hu: "Pillanatérték u", en: "Instantaneous value u"}, u, "V");
  show({hu: "Effektív érték U = Û/√2", en: "RMS value U = Û/√2"}, P.Um / sqrt(2), "V");
  show({hu: "Periódusidő T = 1/f", en: "Period T = 1/f"}, 1000 / P.f, "ms");
  plot("u", u, {unit: "V", color: C.blue});
});
